using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DazzlingLightAction", menuName = "Data/Battle/Battle Actions/Austra/DazzlingLight Action")]
public class DazzlingLightAction : DiceOnHandBasedPurifyAction
{
	[SerializeField]
	protected PurifyAction secondPurifyAction;

	[SerializeField]
	protected OmenLogic secondPurifyOmenLogic;

	public PurifyAction SecondPurifyAction => secondPurifyAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		diceList.AddRange(base.playerDiceHand);
		DefaultCast(target, amount, source);
	}

	private void DefaultCast(GameObject target, int amount, GameObject source)
	{
		int purifyAmount = GetPurifyAmount(amount);
		for (int i = 0; i < diceList.Count; i++)
		{
			bool flag = false;
			DiceInstance diceInstance = diceList[i];
			if (diceInstance.ActionFace.BattleAction is ConfuseAction)
			{
				diceInstance.ActionFace.ActionValue *= 2;
				flag = true;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is ConfuseAction)
			{
				diceInstance.ActionFace.SecondActionValue *= 2;
				flag = true;
			}
			if (flag)
			{
				if (IsSecondVFXEnabled())
				{
					GetSecondVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
				}
				diceInstance.UpdateDiceFace();
				SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray: false, i, diceInstance);
			}
		}
		SpawnVFX(4f);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		secondPurifyAction.CastTargetAmount(target, amount, source);
		if (purifyAmount > 0)
		{
			targetToPurifyLogic.ActivateOmen(purifyAction, purifyAmount, null, source);
		}
		ResetVariables();
	}

	public override int GetPurifyAmount(int amount)
	{
		int num = 0;
		for (int i = 0; i < base.playerDiceHand.Count; i++)
		{
			DiceInstance diceInstance = base.playerDiceHand[i];
			if (diceInstance.ActionFace.BattleAction is ConfuseAction)
			{
				num++;
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is ConfuseAction)
			{
				num++;
			}
		}
		return num * amount;
	}
}
